mapper.sql:
t.TENANT_ID_=#{tenantText}
AND CAST(t.TENANT_ID_ AS BINARY)=CAST(#{tenantText} AS BINARY) AND CAST(d.KEY_ AS BINARY)=CAST('mes-edhr-batch-execution-void-v1' AS BINARY) AND CAST(d.TENANT_ID_ AS BINARY)=CAST(#{tenantText} AS BINARY) AND CAST(p.TENANT_ID_ AS BINARY)=CAST(#{tenantText} AS BINARY)
AND t.ID_=#{taskId} AND CAST(t.ID_ AS BINARY)=CAST(#{taskId} AS BINARY) AND ()
AND t.END_TIME_ IS NOT NULL AND (t.TASK_DEF_KEY_ IS NULL OR t.TASK_DEF_KEY_ != #{startNode}) AND t.ASSIGNEE_=#{userText}
AND t.SUSPENSION_STATE_=1
AND (t.ASSIGNEE_=#{userText} OR (t.ASSIGNEE_ IS NULL AND EXISTS ( SELECT 1 FROM ACT_RU_IDENTITYLINK il WHERE CAST(il.TASK_ID_ AS BINARY)=CAST(t.ID_ AS BINARY) AND il.TYPE_='candidate' AND CAST(il.TASK_ID_ AS BINARY)=CAST(t.ID_ AS BINARY)
AND il.TYPE_='candidate' AND (il.USER_ID_=#{userText} OR il.GROUP_ID_ IN #{g} )
AND (il.USER_ID_=#{userText} OR il.GROUP_ID_ IN (SELECT m.GROUP_ID_ FROM ACT_ID_MEMBERSHIP m WHERE m.USER_ID_=#{userText}))
)) OR ())
AND (LOWER(t.NAME_) LIKE #{keyword} ESCAPE '!' OR LOWER(t.PROC_INST_ID_) LIKE #{keyword} ESCAPE '!' OR LOWER(CAST(rr.id AS CHAR)) LIKE #{keyword} ESCAPE '!' OR LOWER(CAST(rr.certificate_id AS CHAR)) LIKE #{keyword} ESCAPE '!' OR LOWER(rr.request_key) LIKE #{keyword} ESCAPE '!' OR LOWER(cv.certificate_no) LIKE #{keyword} ESCAPE '!' OR LOWER(cs.product_name) LIKE #{keyword} ESCAPE '!' OR (o.authority_type='CONTROLLED_FILE' AND EXISTS ( SELECT 1 FROM dcc_controlled_file searched WHERE searched.tenant_id=#{tenant} AND CAST(CAST(searched.id AS CHAR) AS BINARY)=CAST(o.authority_id AS BINARY) AND (LOWER(searched.title) LIKE #{keyword} ESCAPE '!' OR LOWER(searched.file_number) LIKE #{keyword} ESCAPE '!'))))

mapper.select:
SELECT DISTINCT t.ID_, t.END_TIME_t.CREATE_TIME_ AS sort_time
FROM  WHERE  
ORDER BY sort_time DESC, CAST(t.ID_ AS BINARY) ASC LIMIT #{limit} OFFSET #{offset}

