FROM ACT_HI_PROCINST p WHERE p.TENANT_ID_=#{tenantText}
AND p.START_USER_ID_=#{userText}
AND LOWER(p.NAME_) LIKE #{keyword} ESCAPE '!'

FROM bpm_process_instance_copy c WHERE c.tenant_id=#{tenant} AND c.deleted=0
AND c.user_id=#{userId}
AND LOWER(c.process_instance_name) LIKE #{keyword} ESCAPE '!'
